L575: /// Normalizes command-hook timeouts. SessionEnd defaults to one second and is capped at three
L576: /// seconds; all other command hooks keep the standard ten-minute default.
L577: fn normalize_command_hook(
L578:     event_name: codex_protocol::protocol::HookEventName,
L579:     timeout_sec: Option<u64>,
L580:     source_path: &Path,
L581:     warnings: &mut Vec<String>,
L582: ) -> u64 {
L583:     if event_name != codex_protocol::protocol::HookEventName::SessionEnd {
L584:         return timeout_sec.unwrap_or(600).max(1);
L585:     }
L586:     let max_timeout_sec = SESSION_END_MAX_TIMEOUT_SEC;
L587:     if timeout_sec.is_some_and(|timeout_sec| timeout_sec > max_timeout_sec) {
L588:         warnings.push(format!(
L589:             "clamping SessionEnd hook timeout to {max_timeout_sec}s in {}",
L590:             source_path.display()
L591:         ));
L592:     }
L593:     timeout_sec
L594:         .unwrap_or(SESSION_END_DEFAULT_TIMEOUT_SEC)
L595:         .clamp(1, max_timeout_sec)
L596: }
