L666:         Some(RequirementSource::SystemRequirementsToml { .. }) => HookSource::System,
L667:         Some(RequirementSource::LegacyManagedConfigTomlFromFile { .. }) => {
L668:             HookSource::LegacyManagedConfigFile
L669:         }
L670:         Some(RequirementSource::LegacyManagedConfigTomlFromMdm) => {
L671:             HookSource::LegacyManagedConfigMdm
L672:         }
L673:         Some(RequirementSource::Composite { sources }) => {
L674:             // Requirements hook composition preserves contributing sources in
L675:             // priority order, but discovery only carries one source for the
L676:             // whole merged hooks field. Use the primary contributor as the best
